// The stage machine (docs/architecture.md, section 3). An application is always in exactly one
// stage, and only the moves in MOVES are allowed, each by the actors its row names. Every move
// produces a StageEvent, so each application keeps a full history.
//
// MOVES matches docs/images/stages.png. If it changes, docs/diagrams/stages.drawio (generated by
// design/diagrams/gen.py) and the table in section 3 change in the same pull request.
import type { Application, StageEvent } from './schemas';

export const STAGES = [
  'queued',
  'planning',
  'needs_answers',
  'review',
  'approved',
  'filling',
  'needs_hand',
  'applied',
  'assessment',
  'interview',
  'offer',
  'rejected',
  'withdrawn',
  'skipped',
  'closed',
  'failed',
] as const;
export type Stage = (typeof STAGES)[number];

/** The daily pipeline, the agent on the Mac, Sashreek, and the mail watcher. */
export const ACTORS = ['pipeline', 'agent', 'you', 'mail'] as const;
export type Actor = (typeof ACTORS)[number];

export interface Move {
  from: Stage;
  to: Stage;
  by: readonly Actor[];
}

/** Stages nothing moves out of. `failed` isn't one: he can retry it. */
export const FINAL_STAGES: readonly Stage[] = ['rejected', 'withdrawn', 'skipped', 'closed'];

/** Stages from which a posting being taken down closes the application (#10). */
const CLOSABLE_BY_PIPELINE: readonly Stage[] = [
  'queued',
  'planning',
  'needs_answers',
  'review',
  'approved',
];
const AFTER_APPLYING: readonly Stage[] = ['applied', 'assessment', 'interview', 'offer'];

export const MOVES: readonly Move[] = [
  // Planning
  { from: 'queued', to: 'planning', by: ['pipeline'] },
  { from: 'planning', to: 'needs_answers', by: ['pipeline'] },
  { from: 'planning', to: 'review', by: ['pipeline'] },
  { from: 'needs_answers', to: 'review', by: ['you'] },
  { from: 'review', to: 'approved', by: ['you'] },
  { from: 'review', to: 'skipped', by: ['you'] },
  // Applying
  { from: 'approved', to: 'filling', by: ['agent'] },
  { from: 'filling', to: 'applied', by: ['agent'] },
  { from: 'filling', to: 'needs_answers', by: ['agent'] },
  { from: 'filling', to: 'needs_hand', by: ['agent'] },
  { from: 'filling', to: 'failed', by: ['agent'] },
  { from: 'failed', to: 'approved', by: ['you'] },
  { from: 'needs_hand', to: 'filling', by: ['you'] },
  { from: 'needs_hand', to: 'applied', by: ['you'] },
  // The posting was taken down, at any stage before applied
  ...CLOSABLE_BY_PIPELINE.map((from): Move => ({ from, to: 'closed', by: ['pipeline'] })),
  { from: 'filling', to: 'closed', by: ['agent'] },
  // After applying
  { from: 'applied', to: 'assessment', by: ['you', 'mail'] },
  { from: 'assessment', to: 'interview', by: ['you', 'mail'] },
  { from: 'interview', to: 'offer', by: ['you'] },
  // Rejected and withdrawn can follow any stage from applied on
  ...AFTER_APPLYING.map((from): Move => ({ from, to: 'rejected', by: ['you', 'mail'] })),
  ...AFTER_APPLYING.map((from): Move => ({ from, to: 'withdrawn', by: ['you'] })),
];

/** An application is created in `queued`, by him or by the pipeline's auto rule. */
export const CREATORS: readonly Actor[] = ['you', 'pipeline'];

export class IllegalMoveError extends Error {
  override readonly name = 'IllegalMoveError';
  constructor(
    readonly from: Stage | null,
    readonly to: Stage,
    readonly by: Actor,
  ) {
    super(
      from !== null
        ? `${by} may not move an application from ${from} to ${to}`
        : to === 'queued'
          ? `${by} may not create an application`
          : `an application is created in queued, not ${to}`,
    );
  }
}

export function movesFrom(from: Stage): Move[] {
  return MOVES.filter((move) => move.from === from);
}

export function canMove(from: Stage, to: Stage, by: Actor): boolean {
  return MOVES.some((move) => move.from === from && move.to === to && move.by.includes(by));
}

/**
 * Moves an application to `to`. Returns the moved application and the event to store with it, in
 * the same write. Throws IllegalMoveError for any move not in the table. `at` is injectable so
 * tests are exact.
 */
export function moveStage(
  app: Application,
  to: Stage,
  by: Actor,
  detail: string | null = null,
  at: Date = new Date(),
): { app: Application; event: StageEvent } {
  if (!canMove(app.stage, to, by)) throw new IllegalMoveError(app.stage, to, by);
  return {
    app: { ...app, stage: to, stageAt: at },
    event: { from: app.stage, to, by, at, detail },
  };
}

/** The event that creates an application. Only `queued`, and only by a creator. */
export function firstEvent(
  stage: Stage,
  by: Actor,
  detail: string | null = null,
  at: Date = new Date(),
): StageEvent {
  if (stage !== 'queued' || !CREATORS.includes(by)) throw new IllegalMoveError(null, stage, by);
  return { from: null, to: stage, by, at, detail };
}

/** Throws unless `event` is a valid first event for an application in `stage`. */
export function assertFirstEvent(stage: Stage, event: StageEvent): void {
  if (event.from !== null || event.to !== stage) {
    throw new IllegalMoveError(event.from, event.to, event.by);
  }
  firstEvent(event.to, event.by, event.detail, event.at);
}

/**
 * The document ID of an event under `applications/{jobKey}/events/`: the move's time in
 * milliseconds, then the move, like `1793887260000_queued_planning`. Milliseconds stay 13 digits
 * until the year 2286, so IDs sort in the order the moves happened, and the security rules can
 * build the same ID from a timestamp to check that a stage change wrote its event (#3).
 */
export function eventId(event: StageEvent): string {
  return `${String(event.at.getTime())}_${event.from ?? 'new'}_${event.to}`;
}

/** Application fields only the stage machine and creation set. `update` refuses them. */
export const STAGE_FIELDS = ['jobKey', 'stage', 'stageAt', 'createdAt'] as const;

/** Throws if a patch tries to change a field only the stage machine may change. */
export function assertKeepsStage(patch: object): void {
  for (const field of STAGE_FIELDS) {
    if (field in patch) {
      throw new Error(`${field} can't be changed with update; stages move through moveStage`);
    }
  }
}
